'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { createPanelReport, renderPanelReport, conditionalRange } = require('../scripts/balance/level3-panel-report');

// Synthetic journals test aggregation and validation; no engine or research
// games are generated by this file.
const roster = ['alpha', 'beta', 'gamma'].map(key => ({ key, id: `${key}@1`, label: key.toUpperCase(), family: 'rook', movement: 'R' }));
const comparisons = roster.flatMap((a, index) => [
  ...roster.slice(index + 1).map(b => ({ id: `${a.key}-v-${b.key}`, kind: 'head', designA: a.id, designB: b.id,
    aKey: a.key, aLabel: a.label, bKey: b.key, bLabel: b.label })),
  { id: `${a.key}-v-ordinary`, kind: 'baseline', designA: a.id, designB: null,
    aKey: a.key, aLabel: a.label, bKey: 'ordinary', bLabel: 'Ordinary army' },
]);
function stage({ nodes = 20000, batch = 0, first = 0, count = 4 } = {}) {
  const openings = Array.from({ length: count }, (_, index) => ({ id: `o${first + index}`, moves: [] }));
  const config = { schemaVersion: 3, name: 'Synthetic report fixture', repetitions: 1,
    engine: { nodes, threads: 1, hashMb: 32, maxPlies: 400 }, openings,
    comparisons: comparisons.map(row => ({ id: row.id, label: `${row.aLabel} versus ${row.bLabel}`,
      armyA: { upgrades: {} }, armyB: { upgrades: {} }, strengthA: { skill: 20 }, strengthB: { skill: 20 } })) };
  const metadata = { kind: 'level3-panel', symmetric: true, rows: roster, columns: [...roster, { key: 'ordinary', label: 'Ordinary army' }], comparisons };
  const schedule = comparisons.flatMap(comparison => openings.flatMap(opening => ['w', 'b'].map(aColor => ({
    id: `${comparison.id}-${opening.id}-${aColor}`, pairId: `${comparison.id}-${opening.id}`, comparisonId: comparison.id,
    openingId: opening.id, aColor, openingMoves: opening.moves,
  }))));
  const manifest = { runId: `synthetic-${nodes}-${batch}`, config, schedule,
    designRegistry: { hash: 'registry' }, designProfile: { hash: 'profile', registryHash: 'registry', variant: 'synthetic-variant' } };
  return { key: `b${batch}-${nodes}`, nodes, batch, config, metadata, manifest, records: [] };
}
function addPair(s, comparisonId, openingId, scores = [1, 0]) {
  for (const [index, aColor] of ['w', 'b'].entries()) {
    const planned = s.manifest.schedule.find(row => row.comparisonId === comparisonId && row.openingId === openingId && row.aColor === aColor);
    const score = scores[index], result = score === 0.5 ? '1/2-1/2' : (score === 1) === (aColor === 'w') ? '1-0' : '0-1';
    s.records.push({ ...planned, attempt: 1, status: 'completed', result, reason: 'checkmate',
      profileHash: 'profile', registryHash: 'registry', registryReference: 'run.json#designRegistry', variant: 'synthetic-variant',
      engine: s.config.engine, whiteStrength: { skill: 20 }, blackStrength: { skill: 20 } });
  }
  return s;
}
function report(stages, targetOpenings = 4) { return createPanelReport({ manifest: { runId: 'synthetic-panel', targetOpenings }, stages, roster }); }

test('empty and partial reports retain the requested campaign denominator', () => {
  const r = report([], 8);
  assert.equal(r.nodes.length, 3);
  assert.equal(r.progress.scheduledGames, 8 * 6 * 2 * 3);
  assert.equal(r.nodes[0].scheduledGames, 96);
  assert.equal(r.nodes[0].declaredScheduledGames, 0);
  assert.equal(report([stage()], 8).nodes[0].scheduledGames, 96);
});
const rowFor = (r, key, nodes = 20000) => r.nodes.find(row => row.nodes === nodes).matrix.rows.find(row => row.key === key);

test('complete pairs preserve perspective, WDL and physical colors, with anchors outside overall', () => {
  const s = stage();
  addPair(s, 'alpha-v-beta', 'o0', [1, 0.5]);
  addPair(s, 'alpha-v-gamma', 'o0', [0.5, 0]);
  addPair(s, 'alpha-v-ordinary', 'o0', [1, 1]);
  const r = report([s]), alpha = rowFor(r, 'alpha'), beta = rowFor(r, 'beta');
  assert.equal(alpha.cells.find(row => row.key === 'beta').score, 0.75);
  assert.equal(beta.cells.find(row => row.key === 'alpha').score, 0.25);
  assert.deepEqual([alpha.overall.wins, alpha.overall.draws, alpha.overall.losses], [1, 2, 1]);
  assert.equal(alpha.overall.score, 0.5);
  assert.equal(alpha.overall.games, 4);
  assert.equal(alpha.ordinary.score, 1);
  assert.equal(alpha.overall.physicalColors[0].score, 0.75);
  assert.equal(alpha.overall.physicalColors[1].score, 0.25);
  assert.equal(beta.cells.find(row => row.key === 'alpha').physicalColors[0].score, 0.5);
  assert.equal(alpha.overall.openingCoverage.shared, 1);
  assert.equal(r.progress.pairedGames, 6);
});

test('overall waits for common cases, while faster cells retain their extra pairs', () => {
  const s = stage();
  addPair(s, 'alpha-v-beta', 'o0', [1, 1]); addPair(s, 'alpha-v-beta', 'o1', [1, 1]);
  addPair(s, 'alpha-v-gamma', 'o1', [0, 0]);
  const r = report([s]), alpha = rowFor(r, 'alpha');
  assert.equal(alpha.cells.find(row => row.key === 'beta').games, 4);
  assert.deepEqual(alpha.overall.openingCoverage.openingIds, ['o1']);
  assert.equal(alpha.overall.score, 0.5);
  assert.equal(rowFor(r, 'beta').overall.score, null);
});

test('unpaired completions, truncations and cancelled attempts do not manufacture scores', () => {
  const s = stage(); addPair(s, 'alpha-v-beta', 'o0');
  s.records[1] = { ...s.records[1], status: 'truncated', result: '*', reason: 'max-plies' };
  addPair(s, 'alpha-v-gamma', 'o0'); s.records.pop();
  const r = report([s]);
  assert.equal(r.progress.pairedGames, 0);
  assert.equal(r.progress.finalizedGames, 3);
  assert.equal(rowFor(r, 'alpha').cells.find(row => row.key === 'beta').score, null);
  assert.equal(rowFor(r, 'alpha').overall.score, null);
});

test('highest valid retry wins; copied lines add no weight; corrupt contexts fail', () => {
  const s = stage(); addPair(s, 'alpha-v-beta', 'o0', [1, 1]);
  const failed = { ...s.records[0], status: 'error', result: '*', reason: 'synthetic' };
  s.records[0] = { ...s.records[0], attempt: 2 };
  s.records.unshift(failed);
  s.records.push(structuredClone(s.records[0]));
  assert.equal(rowFor(report([s]), 'alpha').cells.find(row => row.key === 'beta').score, 1);
  assert.equal(report([s]).progress.pairedGames, 2);
  const bad = structuredClone(s); bad.records[1].engine = { ...bad.records[1].engine, nodes: 40000 };
  assert.throws(() => report([bad]), /context changed/);
  const conflict = structuredClone(s); conflict.records.push({ ...conflict.records[1], result: '0-1' });
  assert.throws(() => report([conflict]), /conflicting duplicate/);
});

test('node cohorts remain separate and sensitivity uses only cases shared by all three', () => {
  const stages = [stage({ nodes: 20000 }), stage({ nodes: 40000 }), stage({ nodes: 80000 })];
  addPair(stages[0], 'alpha-v-beta', 'o0', [0, 0]); addPair(stages[0], 'alpha-v-beta', 'o1', [1, 1]);
  addPair(stages[1], 'alpha-v-beta', 'o0', [0.5, 0.5]);
  addPair(stages[2], 'alpha-v-beta', 'o0', [1, 1]); addPair(stages[2], 'alpha-v-beta', 'o2', [0, 0]);
  const r = report(stages), matchup = r.sensitivity.find(row => row.id === 'alpha-v-beta');
  assert.deepEqual(matchup.openingIds, ['o0']);
  assert.deepEqual(matchup.conditions.map(row => row.score), [0, 0.5, 1]);
  assert.equal(matchup.delta20kTo80k, 1);
  assert.equal(matchup.conditionalRange.available, false);
  assert.equal(rowFor(r, 'alpha').cells.find(row => row.key === 'beta').score, 0.5);
  assert.equal(rowFor(r, 'alpha', 80000).cells.find(row => row.key === 'beta').score, 0.5);
});

test('disjoint batches append openings, reused cases and changed declarations fail', () => {
  const one = stage(), two = stage({ batch: 1, first: 4 });
  addPair(one, 'alpha-v-beta', 'o0', [1, 1]); addPair(two, 'alpha-v-beta', 'o4', [0, 0]);
  const r = report([one, two], 8);
  assert.equal(r.nodes[0].declaredOpenings, 8);
  assert.equal(rowFor(r, 'alpha').cells.find(row => row.key === 'beta').games, 4);
  assert.throws(() => report([one, one]), /stage identity/);
  assert.throws(() => report([one, stage({ batch: 1 })], 8), /overlap/);
  const changed = stage({ nodes: 40000 }); changed.config.openings[0].moves = ['e2e4'];
  assert.throws(() => report([one, changed]), /shared opening prefix/);
  const missing = stage(); missing.metadata.comparisons = missing.metadata.comparisons.slice(1);
  assert.throws(() => report([missing]), /every unordered matchup/);
  const renamed = stage({ nodes: 40000 });
  renamed.metadata = structuredClone(renamed.metadata);
  renamed.metadata.comparisons[0].id = 'renamed'; renamed.config.comparisons[0].id = 'renamed';
  assert.throws(() => report([one, renamed]), /rename a shared comparison/);
  assert.throws(() => report([one, two], 4), /below an existing/);
});

test('whole-opening bootstrap is deterministic and preserves paired search deltas', () => {
  const values = [-1, -0.5, 0.5, 1, 0, 0, 0, 0];
  const range = conditionalRange(values, 'fixed');
  assert.deepEqual(conditionalRange(values, 'fixed'), range);
  assert.equal(range.groups, 8); assert.equal(range.unit, 'whole-opening-case');
  assert.ok(range.lower < 0); assert.ok(range.upper > 0);
  const s = stage();
  for (const [index, scores] of [[0, [0, 0]], [1, [0.5, 0]], [2, [1, 0.5]], [3, [1, 1]]]) addPair(s, 'alpha-v-beta', `o${index}`, scores);
  const r = report([s]), direct = rowFor(r, 'alpha').cells.find(row => row.key === 'beta').conditionalRange,
    inverted = rowFor(r, 'beta').cells.find(row => row.key === 'alpha').conditionalRange;
  assert.ok(Math.abs(inverted.lower - (1 - direct.upper)) < 1e-12);
  assert.ok(Math.abs(inverted.upper - (1 - direct.lower)) < 1e-12);
});

test('Markdown shows percentages, WDL, separate anchors and matched node deltas without Elo claims', () => {
  const s = stage(); addPair(s, 'alpha-v-beta', 'o0', [1, 0.5]); addPair(s, 'alpha-v-gamma', 'o0', [0, 0]);
  const output = renderPanelReport(report([s]));
  assert.match(output, /75\.00%/); assert.match(output, /1 \/ 1 \/ 0/);
  assert.match(output, /Ordinary army/); assert.match(output, /Overall score/);
  assert.match(output, /40,000 nodes/); assert.match(output, /80k minus 20k \(pp\)/);
  assert.match(output, /conditional ranges/); assert.match(output, /do not establish an intrinsic piece Elo/);
  assert.equal(createPanelReport({ roster }).nodes.length, 3);
});
